<template>
  <div class="run-detail" v-loading="loading">
    <PageHeader :title="`${summary.plan_name||summary.project_name||'测试运行'} · RUN-${runId.slice(0,8)}`" description="完整执行证据、失败断言与运行事件时间线。">
      <template #actions><el-button v-if="canCancel" type="danger" plain @click="cancel">取消运行</el-button><el-button type="primary" :disabled="!summary.report_id" @click="$router.push(`/report/${summary.report_id}`)">查看报告</el-button></template>
    </PageHeader>
    <el-alert v-if="run?.error_message" :title="run.error_message" type="error" show-icon :closable="false"/>
    <el-descriptions :column="5" border class="context"><el-descriptions-item label="项目">{{summary.project_name||'—'}}</el-descriptions-item><el-descriptions-item label="环境">{{summary.environment_name||'未记录'}}</el-descriptions-item><el-descriptions-item label="代码版本"><span class="mono">{{shortVersion(summary.code_version)}}</span></el-descriptions-item><el-descriptions-item label="触发方式">{{triggerLabel(summary.trigger_type)}}</el-descriptions-item><el-descriptions-item label="触发人">{{summary.actor_name||'系统'}}</el-descriptions-item></el-descriptions>
    <div class="metric-grid"><el-card v-for="item in metrics" :key="item.label" shadow="never"><span>{{item.label}}</span><strong :class="item.class">{{item.value}}</strong><small v-if="item.tip">{{item.tip}}</small></el-card></div>
    <el-card shadow="never"><template #header><div class="card-head"><div><b>失败用例</b><p>对比期望断言和本次真实响应，点击用例进入断言配置。</p></div><el-tag v-if="summary.results_failed" type="danger">{{summary.results_failed}} 个失败</el-tag></div></template><el-table :data="summary.failed_cases||[]"><el-table-column label="用例" min-width="190"><template #default="{row}"><el-link type="primary" @click="$router.push(`/case-assert/${row.case_id}`)">{{row.case_name}}</el-link></template></el-table-column><el-table-column prop="reason" label="失败原因" min-width="220" show-overflow-tooltip/><el-table-column label="断言差异" min-width="320"><template #default="{row}"><div class="diff"><span>期望 <code>{{expectedText(row.expected)}}</code></span><span>实际 <code>{{row.actual?.status_code??'无响应'}}</code></span></div></template></el-table-column><el-table-column label="响应时间" width="110"><template #default="{row}">{{row.response_time_ms?`${Math.round(row.response_time_ms)} ms`:'—'}}</template></el-table-column></el-table><el-empty v-if="!summary.failed_cases?.length" description="本次运行没有失败用例" :image-size="60"/></el-card>
    <el-card shadow="never"><template #header><div class="card-head"><div><b>执行事件时间线</b><p>从任务创建到报告完成的不可变事件证据。</p></div><StatusPill :status="run?.status" :map="RUN_STATUS"/></div></template><el-timeline v-if="events.length"><el-timeline-item v-for="event in events" :key="`${event.sequence}-${event.created_at}`" :timestamp="formatTime(event.created_at)" :type="eventType(event.event_type)"><b>{{eventLabel(event.event_type)}}</b><p v-if="event.payload?.error">{{event.payload.error}}</p><small v-else-if="event.payload?.message">{{event.payload.message}}</small></el-timeline-item></el-timeline><el-empty v-else description="暂无运行事件，任务启动后会自动记录"/></el-card>
  </div>
</template>
<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useRoute } from 'vue-router'
import dayjs from 'dayjs'
import { ElMessage, ElMessageBox } from 'element-plus'
import { testRunApi } from '@/api'
import { RUN_STATUS, TRIGGER_LABELS } from '@/constants/status'
import PageHeader from '@/components/PageHeader.vue'
import StatusPill from '@/components/StatusPill.vue'
const route=useRoute(),runId=String(route.params.id),loading=ref(false),run=ref<any>(null),events=ref<any[]>([]),summary=ref<any>({})
const canCancel=computed(()=>['pending','executing','pulling','analyzing','generating','reporting'].includes(run.value?.status))
const metrics=computed(()=>[{label:'用例总数',value:summary.value.results_total??summary.value.cases_total??'—'},{label:'通过',value:summary.value.results_passed??'—',class:'ok'},{label:'失败',value:summary.value.results_failed??'—',class:'bad'},{label:'总耗时',value:duration(summary.value.duration_ms),tip:summary.value.median_response_ms?`响应中位数 ${Math.round(summary.value.median_response_ms)} ms`:''}])
function formatTime(v:string){return v?dayjs(v).format('YYYY-MM-DD HH:mm:ss'):'—'}function duration(ms:number){if(ms===null||ms===undefined)return'—';return ms<1000?`${ms} ms`:`${(ms/1000).toFixed(1)} s`}function shortVersion(v:string){return v?v.length>20?`${v.slice(0,12)}…`:v:'—'}function triggerLabel(v:string){return TRIGGER_LABELS[v]||v||'手动'}
function eventType(v:string){return v?.includes('failed')?'danger':v?.includes('completed')?'success':'primary'}function eventLabel(v:string){return({'run.created':'运行已创建','run.started':'开始执行','run.completed':'执行完成','run.failed':'执行失败','case.started':'开始用例','case.completed':'用例完成','report.generated':'报告已生成'} as any)[v]||v}
function expectedText(v:any){if(v?.status_code)return`HTTP ${v.status_code}`;if(v?.assertions?.length)return`${v.assertions.length} 条规则`;return'已配置断言'}
async function load(){loading.value=true;try{const [a,b,c]:any=await Promise.all([testRunApi.get(runId),testRunApi.getEvents(runId),testRunApi.getExecSummary(runId)]);run.value=a?.data;events.value=b?.data?.list||[];summary.value=c?.data||{}}finally{loading.value=false}}
async function cancel(){try{await ElMessageBox.confirm('确定取消本次运行？','取消运行',{type:'warning'})}catch{return}await testRunApi.cancel(runId);ElMessage.success('已提交取消请求');await load()}onMounted(load)
</script>
<style scoped>
.run-detail{display:grid;gap:16px}.context{margin-top:0}.mono{font-family:ui-monospace,SFMono-Regular,Menlo,monospace}.metric-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.metric-grid span,.metric-grid small,.card-head p{display:block;color:var(--app-text-secondary);font-size:12px}.metric-grid strong{display:block;margin-top:7px;font-size:26px}.metric-grid strong.ok{color:var(--el-color-success)}.metric-grid strong.bad{color:var(--el-color-danger)}.metric-grid small{margin-top:5px}.card-head{display:flex;justify-content:space-between;align-items:flex-start}.card-head p{margin:5px 0 0}.diff{display:flex;gap:12px;flex-wrap:wrap}.diff span{font-size:12px;color:var(--app-text-secondary)}.diff code{padding:3px 6px;border-radius:4px;background:var(--el-fill-color-light);color:var(--el-text-color-primary)}.el-timeline p{margin:4px 0;color:var(--el-color-danger)}.el-timeline small{color:var(--app-text-secondary)}@media(max-width:900px){.metric-grid{grid-template-columns:1fr 1fr}.context :deep(.el-descriptions__body){overflow:auto}}@media(max-width:520px){.metric-grid{grid-template-columns:1fr}}
</style>
